package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string = ""
var WsBalEd string = ""
var WsTotEd string = ""

var ledgerFile *os.File
var ledgerReader *bufio.Reader
var ledgerRec LedgerRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEdited(value decimal.Decimal, picture string) string {
	// Determine sign handling
	hasSign := len(picture) > 0 && picture[0] == '-'
	pic := picture
	if hasSign {
		pic = picture[1:]
	}
	// count integer and fractional digit placeholders
	// pic contains Z,9,',','.'
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intDigits := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	// Truncate/high-order drop: modulo 10^intDigits for integer part
	neg := value.IsNegative()
	absVal := value
	if neg {
		absVal = absVal.Neg()
	}
	// Ensure scale for rounding/truncation: we use trunc to fracDigits
	// Values already have correct scale, but ensure
	// For formatting, we need integer and fraction parts
	// Use absolute value
	// Get integer part modulo
	// decimal: absVal *10^fracDigits  -> integer
	// simpler: format with string
	// Compute integer part = floor(absVal)
	intPartDec := absVal.Truncate(0)
	// fractional part with fracDigits
	// Get absVal truncated to fracDigits (not rounded, but values are exact)
	// We'll get fractional digits by (absVal - intPart) * 10^frac
	var fracInt int64
	if fracDigits > 0 {
		pow := decimal.NewFromInt(1)
		for i := 0; i < fracDigits; i++ {
			pow = pow.Mul(decimal.NewFromInt(10))
		}
		fracDec := absVal.Sub(intPartDec).Mul(pow).Truncate(0)
		// Due to decimal representation, ensure positive
		fracInt = fracDec.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
		// Handle high-order drop for integer part modulo
	}
	// modulo integer
	intPartInt := intPartDec.IntPart()
	// dec IntPart may overflow for large, but our sizes small
	if intDigits > 0 {
		mod := int64(1)
		for i := 0; i < intDigits; i++ {
			mod *= 10
		}
		intPartInt = intPartInt % mod
		if intPartInt < 0 {
			intPartInt = -intPartInt
		}
	}
	// Build digit strings
	intStr := fmt.Sprintf("%0*d", intDigits, intPartInt)
	fracStr := ""
	if fracDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracInt)
	}
	// Map intStr digits onto intPic placeholders
	// intPic length includes commas
	outInt := make([]byte, len(intPic))
	digitIdx := 0
	for i := range intPic {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			outInt[i] = intStr[digitIdx]
			digitIdx++
		} else {
			// comma
			outInt[i] = byte(c)
		}
	}
	// Z suppression
	// Find last mandatory '9' position in intPic (for integer part)
	// All Z's left of all 9's that are zero should become spaces
	// Standard: suppress leading zeros where placeholder is Z and all more significant digit placeholders are zero
	// We can iterate left to right; keep flag supressing
	suppressing := true
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			if outInt[i] != '0' {
				suppressing = false
			}
			if suppressing {
				if c == 'Z' {
					outInt[i] = ' '
				} else { // '9' mandatory: show zero, stop suppressing (but we already set)
					// keep '0'
					suppressing = false
				}
			} else {
				// keep digit as is
			}
		} else if c == ',' {
			if suppressing {
				// if still suppressing, comma becomes space
				// But need to check if all digit placeholders to right up to next digit? Actually COBOL replaces commas in suppress zone with spaces.
				outInt[i] = ' '
			}
		}
	}
	// Special case: if integer part is zero and suppression blanked everything before the mandatory 9, the mandatory 9 remains '0'
	// Already handled.

	// Assemble final pic part
	formattedPic := string(outInt)
	if dotIdx >= 0 {
		formattedPic = formattedPic + "." + fracStr
	}
	if hasSign {
		signChar := ' '
		if neg {
			signChar = '-'
		}
		return string(signChar) + formattedPic
	}
	return formattedPic
}

func moveToAmtEd(v decimal.Decimal) {
	WsAmtEd = formatEdited(v, "ZZ,ZZ9.99")
}
func moveToBalEd(v decimal.Decimal) {
	WsBalEd = formatEdited(v, "-Z,ZZZ,ZZ9.99")
}
func moveToTotEd(v decimal.Decimal) {
	WsTotEd = formatEdited(v, "-ZZZ,ZZZ,ZZ9.99")
}

func mainPara() {
	var err error
	ledgerFile, err = os.Open("input.dat")
	if err != nil {
		// If file not exists, treat as empty
		ledgerFile = nil
		ledgerReader = bufio.NewReader(strings.NewReader(""))
		WsEofFlag = "Y"
	} else {
		defer ledgerFile.Close()
		ledgerReader = bufio.NewReader(ledgerFile)
	}
	readPara()
	for !isInputDone() {
		processPara()
	}
	if !isFirstRecord() {
		acctBreakPara()
		branchBreakPara()
	}
	if ledgerFile != nil {
		ledgerFile.Close()
	}
	grandPara()
}

func readPara() {
	// LINE SEQUENTIAL: read one line
	line, err := ledgerReader.ReadString('\n')
	if err != nil {
		// EOF
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
		// last line without newline
	}
	// Remove trailing \n and \r
	line = strings.TrimRight(line, "\r\n")
	// Pad with spaces to 14
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	}
	if len(line) > 14 {
		line = line[:14]
	}
	brBranch := line[0:2]
	brAcct := line[2:6]
	brType := line[6:7]
	brAmtStr := line[7:14]
	// BR-AMT digits only
	brAmtStr = strings.TrimSpace(brAmtStr)
	// Actually PIC 9(5)V99 stores digits only; if line had spaces padding, TrimSpace may remove, but digits are zero-padded
	// Use original slice without trim for spaces: treat spaces as zero?
	// Simpler: parse digits from raw slice
	rawAmt := line[7:14]
	digits := ""
	for _, ch := range rawAmt {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	// If no digits (blank line), treat as 0
	if digits == "" {
		digits = "0"
	}
	// Build decimal: digits integer * 10^-2
	n := decimal.RequireFromString(digits)
	// digits may have leading zeros, RequireFromString handles
	amt := n.Shift(-2)

	ledgerRec.BrBranch = brBranch
	ledgerRec.BrAcct = brAcct
	ledgerRec.BrType = brType
	ledgerRec.BrAmt = amt
	if err != nil && line == "" {
		// already set done above, but we parsed a line; check original err
	}
	// Check if we actually hit EOF: if ReadString returned io.EOF, next call will get EOF, but we already consumed line
	// Need to detect EOF after: if err != nil (io.EOF) then next read should be EOF; we keep WsEofFlag = N for this record
	// To detect end, peek next byte?
	// Instead, rely on next call to readPara detecting EOF when ReadString returns error with no data
	// So we don't set done now. But we need to know if this was last line and next read will be EOF: that's fine
	// However if file empty, we already handled first read with len 0
	// So we need to check if after reading, we are at EOF and no more data: we can't know until next read
	// So keep flag N
	// But if we got error io.EOF with data, we still have a record; don't mark done
	// Only if we got error and no data (handled at top) mark done
	// So do nothing
	// To avoid infinite loop, we need to detect that next read will be EOF; it will be caught next invocation
	// But if the last line was read with io.EOF, the bufio Reader will next return EOF with empty string
	// So okay
	if err != nil {
		// We have consumed the last line; next read will be EOF
		// Need to remember that we have buffered? Actually we already set WsEofFlag stays N, so loop will process this record, then next read will set done
		// However if file ended exactly at newline, the next read will return EOF empty, so fine
		// No action
		_ = err
	}
	// Special: if line was empty due to EOF (already returned), not here
	// Need to handle case where file had no newline at end but we already set - we correctly didn't mark done
}

func processPara() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			acctBreakPara()
			branchBreakPara()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				acctBreakPara()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	postPara()
	readPara()
}

func postPara() {
	moveToAmtEd(ledgerRec.BrAmt)
	switch ledgerRec.BrType {
	case "D":
		WsBal = WsBal.Add(ledgerRec.BrAmt)
		// DISPLAY BR-ACCT " D " WS-AMT-ED
		fmt.Println(ledgerRec.BrAcct + " D " + WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(ledgerRec.BrAmt)
		fmt.Println(ledgerRec.BrAcct + " C " + WsAmtEd)
	default:
		WsSkipped++
		// low-order truncation for PIC 99: keep modulo 100
		// WsSkipped is int64, but display will be modulo
		fmt.Println(ledgerRec.BrAcct + " ? SKIPPED")
	}
}

func acctBreakPara() {
	moveToBalEd(WsBal)
	fmt.Println("  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd)
	WsBranchTot = WsBranchTot.Add(WsBal)
	WsBal = decimal.NewFromInt(0)
}

func branchBreakPara() {
	moveToTotEd(WsBranchTot)
	fmt.Println(" BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd)
	WsGrandTot = WsGrandTot.Add(WsBranchTot)
	WsBranchTot = decimal.NewFromInt(0)
}

func grandPara() {
	moveToTotEd(WsGrandTot)
	fmt.Println("GRAND TOTAL:" + WsTotEd)
	// DISPLAY "SKIPPED: " WS-SKIPPED -> PIC 99 zero-padded 2
	skippedDisplay := fmt.Sprintf("%02d", WsSkipped%100)
	fmt.Println("SKIPPED: " + skippedDisplay)
}

func main() {
	// Ensure working storage initial pads
	WsPrevBranch = padRight(WsPrevBranch, 2)
	WsPrevAcct = padRight(WsPrevAcct, 4)
	mainPara()
}
